INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(1922, 192, 'reading', 'Reading Passage 2: Athletes and stress', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
                                            Questions 14-18                                                                                                                                                
                                                                                                                                    </h2>
