-- Section 1923: Reading Passage 3: An inquiry into the existence of the gifted child
INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(1923, 192, 'reading', 'Reading Passage 3: An inquiry into the existence of the gifted child', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
                                            Questions 27-32                                                                                                                                                
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <p>Complete the summary using the list of phrases, A-K, below.</p>
<p>Write the correct letter, A-K, in boxes on your answer sheet.</p>
<table>
<tbody>
<tr>
<td><strong>A</strong> appeal</td>
<td><strong>B</strong> determined</td>
<td><strong>C</strong> intrigued</td>
</tr>
<tr>
<td><strong>D</strong> single</td>
<td><strong>E</strong> achievement</td>
<td><strong>F</strong> devoted</td>
</tr>
<tr>
<td><strong>G</strong> involved</td>
<td><strong>H</strong> unique</td>
<td><strong>I</strong> innovative</td>
</tr>
<tr>
<td><strong>J</strong> satisfaction</td>
<td><strong>K</strong> intent</td>
</tr>
</tbody>
</table>
<p style="text-align: center"><strong>Maryam Mirzakhani</strong></p>
<p>Maryam Mirzakhani is regarded as <span class="ielts-reading-question-item"><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">27</strong><select data-qnum="27" name="question_27" class="ielts-inline-select"><option value="">[ 27 ] Tanlang...</option><option value="A. appeal">A. appeal</option><option value="B. determined">B. determined</option><option value="C. intrigued">C. intrigued</option><option value="D. single">D. single</option><option value="E. achievement">E. achievement</option><option value="F. devoted">F. devoted</option><option value="G. involved">G. involved</option><option value="H. unique">H. unique</option><option value="I. innovative">I. innovative</option><option value="J. satisfaction">J. satisfaction</option><option value="K. intent">K. intent</option></select></span></span> in the field of mathematics because she was the only female holder of the prestigious Fields Medal - a record that she retained at the time of her death. However, maths held little <span class="ielts-reading-question-item"><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">28</strong><select data-qnum="28" name="question_28" class="ielts-inline-select"><option value="">[ 28 ] Tanlang...</option><option value="A. appeal">A. appeal</option><option value="B. determined">B. determined</option><option value="C. intrigued">C. intrigued</option><option value="D. single">D. single</option><option value="E. achievement">E. achievement</option><option value="F. devoted">F. devoted</option><option value="G. involved">G. involved</option><option value="H. unique">H. unique</option><option value="I. innovative">I. innovative</option><option value="J. satisfaction">J. satisfaction</option><option value="K. intent">K. intent</option></select></span></span> for her as a child and in fact her performance was below average until she was <span class="ielts-reading-question-item"><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">29</strong><select data-qnum="29" name="question_29" class="ielts-inline-select"><option value="">[ 29 ] Tanlang...</option><option value="A. appeal">A. appeal</option><option value="B. determined">B. determined</option><option value="C. intrigued">C. intrigued</option><option value="D. single">D. single</option><option value="E. achievement">E. achievement</option><option value="F. devoted">F. devoted</option><option value="G. involved">G. involved</option><option value="H. unique">H. unique</option><option value="I. innovative">I. innovative</option><option value="J. satisfaction">J. satisfaction</option><option value="K. intent">K. intent</option></select></span></span> by a difficult puzzle that one of her siblings showed her.</p>
<p>Later, as a professional mathematician, she had an inquiring mind and proved herself to be <span class="ielts-reading-question-item"><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">30</strong><select data-qnum="30" name="question_30" class="ielts-inline-select"><option value="">[ 30 ] Tanlang...</option><option value="A. appeal">A. appeal</option><option value="B. determined">B. determined</option><option value="C. intrigued">C. intrigued</option><option value="D. single">D. single</option><option value="E. achievement">E. achievement</option><option value="F. devoted">F. devoted</option><option value="G. involved">G. involved</option><option value="H. unique">H. unique</option><option value="I. innovative">I. innovative</option><option value="J. satisfaction">J. satisfaction</option><option value="K. intent">K. intent</option></select></span></span> when things did not go smoothly. She said she got the greatest <span class="ielts-reading-question-item"><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">31</strong><select data-qnum="31" name="question_31" class="ielts-inline-select"><option value="">[ 31 ] Tanlang...</option><option value="A. appeal">A. appeal</option><option value="B. determined">B. determined</option><option value="C. intrigued">C. intrigued</option><option value="D. single">D. single</option><option value="E. achievement">E. achievement</option><option value="F. devoted">F. devoted</option><option value="G. involved">G. involved</option><option value="H. unique">H. unique</option><option value="I. innovative">I. innovative</option><option value="J. satisfaction">J. satisfaction</option><option value="K. intent">K. intent</option></select></span></span> from making ground-breaking discoveries and in fact she was responsible for some extremely <span class="ielts-reading-question-item"><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">32</strong><select data-qnum="32" name="question_32" class="ielts-inline-select"><option value="">[ 32 ] Tanlang...</option><option value="A. appeal">A. appeal</option><option value="B. determined">B. determined</option><option value="C. intrigued">C. intrigued</option><option value="D. single">D. single</option><option value="E. achievement">E. achievement</option><option value="F. devoted">F. devoted</option><option value="G. involved">G. involved</option><option value="H. unique">H. unique</option><option value="I. innovative">I. innovative</option><option value="J. satisfaction">J. satisfaction</option><option value="K. intent">K. intent</option></select></span></span> mathematical studies.</p>
