-- Section 1932: Reading Passage 2: The global importance of wetlands
INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(1932, 193, 'reading', 'Reading Passage 2: The global importance of wetlands', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
                                            Questions 14-17                                                                                                                                                
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <p>Which paragraph contains the following information?</p>
<p><em>Write the correct letter, <strong>A-H</strong>, in boxes on your answer sheet.</em></p>
                                        </div>
