INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(1933, 193, 'reading', 'Reading Passage 3: Is the era of artificial speech translation upon us?', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
