-- Section 1942: Reading Passage 2: Deep-sea Mining
INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(1942, 194, 'reading', 'Reading Passage 2: Deep-sea Mining', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
